    var THEMES = ['Virunga National Park', 'Congo River', 'Kinshasa', 'Okapi', 'Bonobo', 'Lubumbashi', 'Lake Kivu', 'Kisangani', 'Congolese rumba', 'Nyiragongo', 'Democratic Republic of the Congo landscape', 'Goma'];
